import { OptimizedImage } from "@/components/common/optimized-image";
import type { ICampaign, IProduct } from "@/type";
import { Link } from "react-router-dom";
import { AddToCart, AddToCartLink } from "./add-to-cart";
import { usePrice } from "@/hooks/usePrice";
import type { IItemTracker } from "@/hooks/useGtmTracker";
import { WishlistToggle } from "./wishlist-toggle";
import { StockOutIcon } from "./icon";
import { renderStars } from "./star-ratting";
import { ShieldCheck, Truck, Users } from "lucide-react";

interface Props {
    p: IProduct;
    campaign?: ICampaign | null;
}

export const ProductCard = ({ p, campaign = null }: Props) => {
    const trackerData: IItemTracker = {
        item_id: p?.id.toString() || "",
        item_name: p?.name || "",
        item_price: p?.price || 0,
        item_quantity: 1,
        item_brand: p?.brand || "",
        item_category: p?.category || "",
    };

    const link = `/products/${p?.slug}${campaign ? "?c=" + campaign?.id : ""}`;

    return (
        <>
            <div
                key={p?.id}
                className="group/card relative flex h-full flex-col overflow-hidden rounded-xl md:rounded-2xl border border-gray-200/80 bg-white transition-all duration-300 ease-out hover:-translate-y-1 hover:border-primary/30 hover:shadow-xl hover:shadow-gray-200/70"
            >
                <div className="relative aspect-square overflow-hidden bg-gradient-to-b from-gray-50 to-gray-100 group/product">
                    <Link to={link} className="absolute z-0 inset-0">
                        <OptimizedImage
                            src={p?.image || ""}
                            className={`absolute h-full w-full z-0 transition-transform duration-700 ease-out group-hover/card:scale-[1.07] ${!p?.in_stock ? "grayscale-[60%] opacity-80" : ""}`}
                            alt={p?.name || "Product Image"}
                        />
                        <span className="pointer-events-none absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-black/10 to-transparent opacity-0 transition-opacity duration-300 group-hover/card:opacity-100" />
                    </Link>

                    {campaign ? (
                        <CampaignDiscount c={campaign} p={p} />
                    ) : (
                        <RegularDiscount p={p} />
                    )}

                    {!p?.in_stock && (
                        <span className="pointer-events-none absolute bottom-2 left-2 z-10 rounded-full bg-gray-900/75 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-white backdrop-blur-sm md:text-[11px]">
                            Sold out
                        </span>
                    )}

                    <SoldChip sold={p?.sold} />

                    <WishlistToggle id={Number(p?.id)} />

                    {!p?.in_stock && (
                        <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center bg-white/5">
                            <span className="rounded-full bg-red-500 px-2.5 py-1 text-[10px] font-semibold uppercase tracking-wider text-white shadow-lg @2xs:px-3.5 @2xs:py-1.5 @2xs:text-xs">
                                Out of stock
                            </span>
                        </div>
                    )}
                </div>

                <div className="flex flex-1 flex-col gap-1 md:gap-1.5 p-2 md:p-3.5 select-none">
                    <Link to={link} className="block">
                        <h3 className="line-clamp-2 min-h-[2.75em] text-[13px] font-medium leading-snug text-gray-800 transition-colors duration-200 hover:text-primary md:text-base md:font-semibold">
                            {p?.name}
                        </h3>
                    </Link>

                    <RatingRow p={p} />

                    <div className="mt-auto pt-0.5">
                        <RegularPrice p={p} />
                    </div>

                    {!p?.in_stock ? (
                        <OutOfStock />
                    ) : p?.has_variants ? (
                        <AddToCartLink slug={link} />
                    ) : (
                        <AddToCart
                            p={{
                                product_id: p?.id,
                                quantity: 1,
                                campaign_id: campaign?.id,
                            }}
                            isInStock={p?.in_stock}
                            trackerData={trackerData}
                        />
                    )}

                    <TrustBadges />
                </div>
            </div>
        </>
    );
};

const RatingRow = ({ p }: { p: IProduct }) => {
    const rating = Number(p?.rating) || 0;
    const count = Number(p?.reviews) || 0;

    return (
        <div
            className="flex items-center gap-1.5"
            aria-label={`Rating: ${rating} out of 5 from ${count} reviews`}
        >
            <div className="flex min-w-0 items-center gap-1">
                <span className="text-lg leading-none tracking-tighter md:text-xl">
                    {renderStars(rating)}
                </span>
                <span className="font-medium text-gray-500 text-xs">
                    ({count}
                    <span className="hidden md:inline">
                        {" "}
                        {count === 1 || count === 0 ? "review" : "reviews"}
                    </span>
                    )
                </span>
            </div>
        </div>
    );
};

const RegularPrice = ({ p }: { p: IProduct }) => {
    const { getPriceWithCurrency } = usePrice();

    return (
        <div className="flex flex-wrap items-baseline gap-x-1.5 gap-y-0 md:gap-x-2">
            {p?.price_range && Object.keys(p?.price_range).length > 0 ? (
                <span className="text-[15px] font-bold tracking-tight text-primary md:text-lg">
                    {getPriceWithCurrency(p?.price_range?.min)} -{" "}
                    {getPriceWithCurrency(p?.price_range?.max)}
                </span>
            ) : (
                <>
                    <span className="text-[15px] font-bold tracking-tight text-primary md:text-xl">
                        {getPriceWithCurrency(p?.price)}
                    </span>
                    {p?.original !== p?.price && (
                        <span className="text-xs font-medium text-gray-400 line-through decoration-gray-400/80 md:text-sm">
                            {getPriceWithCurrency(p?.original)}
                        </span>
                    )}{" "}
                </>
            )}
        </div>
    );
};

interface ICP {
    p: IProduct;
    c: ICampaign;
}

const RegularDiscount = ({ p }: { p: IProduct }) => {
    const { getCurrencySymbol } = usePrice();
    if (!p?.discount) return null;
    if (p?.discount === 0) return null;

    const amount =
        p?.discount_type === "percent"
            ? `-${p?.discount}%`
            : `-${getCurrencySymbol()}${p?.discount}`;

    return <DiscountLabel>{amount}</DiscountLabel>;
};
const CampaignDiscount = ({ c }: ICP) => {
    const { getCurrencySymbol } = usePrice();
    if (!c || c?.status !== "active") return null;

    const label =
        c.discount_type === "percent"
            ? `-${c.discount_amount}%`
            : `-${getCurrencySymbol()}${c?.discount_amount}`;

    return <DiscountLabel>{label}</DiscountLabel>;
};

const DiscountLabel = ({ children }: { children: string }) => {
    return (
        <div className="absolute left-2 top-2 z-10 rounded-full bg-gradient-to-r from-rose-500 to-red-600 px-2 py-0.5 text-[10px] font-bold tracking-wide text-white shadow-md shadow-red-500/30 ring-1 ring-white/40 md:left-3 md:top-3 md:px-2.5 md:py-1 md:text-xs flex items-center">
            {children}
        </div>
    );
};

const OutOfStock = () => (
    <button className="mt-1 flex h-9 w-full cursor-not-allowed items-center justify-center gap-1 rounded-3xl border border-dashed border-red-300 bg-red-50 text-sm font-medium text-red-500 transition-all duration-300 md:mt-2 md:h-10 md:gap-2 md:text-base">
        <StockOutIcon />
        Out of stock
    </button>
);

const SoldChip = ({ sold }: { sold: number }) => (
    <span className="pointer-events-none absolute bottom-1.5 left-1.5 z-10 inline-flex max-w-[calc(100%-0.75rem)] items-center gap-1 rounded-full bg-white/95 px-1.5 py-0.5 text-[10px] font-semibold text-gray-800 shadow-sm ring-1 ring-gray-900/5 @min-[12.5rem]:bottom-2 @min-[12.5rem]:left-2 @min-[12.5rem]:px-2 @min-[12.5rem]:text-[11px] @2xs:gap-1.5 @2xs:py-1 @2xs:text-xs @sm:bottom-3 @sm:left-3 @sm:px-3 @sm:text-sm">
        <Users className="size-3 shrink-0 text-primary @2xs:size-3.5 @sm:size-4" />
        <span className="truncate">
            {sold} {sold === 1 || sold === 0 ? "sale" : "sales"}
        </span>
    </span>
);

const TrustBadges = () => (
    <div className="mt-0.5 flex items-center justify-center gap-1.5 border-t border-dashed border-gray-200 pt-1.5 text-[10px] font-medium text-gray-500 md:mt-1 md:gap-2.5 md:pt-2 md:text-xs">
        <span className="inline-flex items-center gap-0.5 whitespace-nowrap md:gap-1 text-emerald-600">
            <ShieldCheck className="size-3 shrink-0 md:size-3.5" />
            100% original
        </span>
        <span
            className="h-3 w-px shrink-0 bg-gray-200 text-primary"
            aria-hidden="true"
        />
        <span className="inline-flex items-center gap-0.5 whitespace-nowrap md:gap-1 text-primary">
            <Truck className="size-3 shrink-0  md:size-3.5" />
            <span className="md:hidden">COD</span>
            <span className="hidden md:inline">Cash on Delivery</span>
        </span>
    </div>
);
